def process(cnvHighEndometrioid, mmc6G) -> pd.DataFrame:
    import pandas as pd

    ha = cnvHighEndometrioid.copy()
    drugs = mmc6G.copy()

    # If upstream returned a diagnostic error row, pass it through
    if 'error' in ha.columns:
        return ha

    if ha.shape[1] == 0:
        return pd.DataFrame([{'error': 'cnvHighEndometrioid returned empty table (no columns)'}])

    if 'gene_name' not in ha.columns:
        ha = ha.rename(columns={ha.columns[0]: 'gene_name'})

    ha['gene_name'] = ha['gene_name'].astype(str).str.strip()
    drugs['gene_name'] = drugs['gene_name'].astype(str).str.strip()

    merged = ha[['gene_name']].drop_duplicates().merge(
        drugs[['gene_name']].drop_duplicates(),
        on='gene_name',
        how='inner'
    )

    out = merged[['gene_name']].drop_duplicates().sort_values('gene_name').reset_index(drop=True)
    return out

def process(mmc1) -> pd.DataFrame:
    import pandas as pd

    df = mmc1.copy()
    # Find histology column
    hist_col = None
    for c in df.columns:
        cl = c.strip().lower()
        if cl in {'histologic_type', 'histologic type'}:
            hist_col = c
            break
    if hist_col is None:
        cand = [c for c in df.columns if 'histologic' in c.lower() and 'type' in c.lower()]
        hist_col = cand[0] if cand else None

    if hist_col is None:
        return pd.DataFrame([{'error': 'Histologic type column not found', 'n_cols': df.shape[1]}])

    endo = df[df[hist_col].astype(str).str.contains('Endometrioid', case=False, na=False)].copy()

    # candidate CNV columns (containing 'cnv')
    cnv_cols = [c for c in df.columns if 'cnv' in c.lower()]
    if not cnv_cols:
        return pd.DataFrame([{'error': 'No columns containing cnv found', 'hist_col': hist_col}])

    # summarize each cnv column for endometrioid rows
    rows = []
    for c in cnv_cols:
        s = endo[c]
        # try numeric
        s_num = pd.to_numeric(s, errors='coerce')
        frac_num = float(s_num.notna().mean())
        row = {
            'cnv_col': c,
            'endo_nonnull': int(s.notna().sum()),
            'endo_unique': int(s.astype(str).nunique(dropna=False)),
            'fraction_numeric_parseable': frac_num,
        }
        if frac_num > 0.8:
            row.update({
                'min': float(s_num.min()),
                'p25': float(s_num.quantile(0.25)),
                'median': float(s_num.median()),
                'p75': float(s_num.quantile(0.75)),
                'max': float(s_num.max()),
            })
        else:
            # categorical preview
            vals = s.dropna().astype(str).str.strip()
            row['top_values'] = '; '.join(list(vals.value_counts().head(10).index))
        rows.append(row)

    out = pd.DataFrame(rows)
    # sort: prefer columns that look categorical first (low frac numeric), then by unique
    out = out.sort_values(['fraction_numeric_parseable', 'endo_unique'], ascending=[True, True]).reset_index(drop=True)
    return out
